-- Teaching Tracker V1 / Supabase schema + RLS
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.semesters(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null,start_date date not null,end_date date not null,is_active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.courses(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,semester_id uuid not null references public.semesters(id) on delete cascade,code text not null,name text not null,room text,color text not null default 'indigo',weekday smallint check(weekday between 0 and 6),class_time time,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.course_sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,course_id uuid not null references public.courses(id) on delete cascade,week_no smallint not null check(week_no between 1 and 30),topic text not null,starts_at timestamptz not null,room text,status text not null default 'planned' check(status in('planned','preparing','ready','taught','archived')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.todos(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,course_id uuid references public.courses(id) on delete cascade,session_id uuid references public.course_sessions(id) on delete cascade,title text not null,priority text not null default 'medium' check(priority in('high','medium','low')),due_at timestamptz,completed boolean not null default false,completed_at timestamptz,notes text,reminder_minutes integer check(reminder_minutes is null or reminder_minutes>=0),recurrence text not null default 'none' check(recurrence in('none','weekly')),recurrence_parent_id uuid references public.todos(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.files(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,course_id uuid references public.courses(id) on delete cascade,session_id uuid references public.course_sessions(id) on delete cascade,name text not null,storage_path text not null,size_bytes bigint,mime_type text,version integer not null default 1 check(version>=1),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.notes(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,session_id uuid not null references public.course_sessions(id) on delete cascade,kind text not null default 'prep' check(kind in('prep','reflection')),body text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.reminders(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,todo_id uuid not null unique references public.todos(id) on delete cascade,remind_at timestamptz not null,sent_at timestamptz,created_at timestamptz not null default now());
create table if not exists public.push_subscriptions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,endpoint text not null unique,p256dh text not null,auth text not null,user_agent text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists idx_courses_user_semester on public.courses(user_id,semester_id);create index if not exists idx_sessions_course_date on public.course_sessions(course_id,starts_at);create index if not exists idx_todos_user_due on public.todos(user_id,due_at);create unique index if not exists idx_todos_one_recurrence_child on public.todos(recurrence_parent_id) where recurrence_parent_id is not null;create index if not exists idx_files_user_course on public.files(user_id,course_id);create index if not exists idx_reminders_due on public.reminders(remind_at) where sent_at is null;
create or replace function public.set_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end;$$;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$begin insert into public.profiles(id,display_name) values(new.id,coalesce(new.raw_user_meta_data->>'display_name',split_part(new.email,'@',1))) on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
drop trigger if exists trg_profiles_updated on public.profiles;create trigger trg_profiles_updated before update on public.profiles for each row execute procedure public.set_updated_at();drop trigger if exists trg_semesters_updated on public.semesters;create trigger trg_semesters_updated before update on public.semesters for each row execute procedure public.set_updated_at();drop trigger if exists trg_courses_updated on public.courses;create trigger trg_courses_updated before update on public.courses for each row execute procedure public.set_updated_at();drop trigger if exists trg_sessions_updated on public.course_sessions;create trigger trg_sessions_updated before update on public.course_sessions for each row execute procedure public.set_updated_at();drop trigger if exists trg_todos_updated on public.todos;create trigger trg_todos_updated before update on public.todos for each row execute procedure public.set_updated_at();drop trigger if exists trg_files_updated on public.files;create trigger trg_files_updated before update on public.files for each row execute procedure public.set_updated_at();drop trigger if exists trg_notes_updated on public.notes;create trigger trg_notes_updated before update on public.notes for each row execute procedure public.set_updated_at();drop trigger if exists trg_push_updated on public.push_subscriptions;create trigger trg_push_updated before update on public.push_subscriptions for each row execute procedure public.set_updated_at();
alter table public.profiles enable row level security;alter table public.semesters enable row level security;alter table public.courses enable row level security;alter table public.course_sessions enable row level security;alter table public.todos enable row level security;alter table public.files enable row level security;alter table public.notes enable row level security;alter table public.reminders enable row level security;alter table public.push_subscriptions enable row level security;
do $$ declare t text;begin foreach t in array array['profiles','semesters','courses','course_sessions','todos','files','notes','reminders','push_subscriptions'] loop execute format('drop policy if exists owner_all on public.%I',t);if t='profiles' then execute 'create policy owner_all on public.profiles for all using(id=auth.uid()) with check(id=auth.uid())';else execute format('create policy owner_all on public.%I for all using(user_id=auth.uid()) with check(user_id=auth.uid())',t);end if;end loop;end $$;
insert into storage.buckets(id,name,public,file_size_limit) values('lecture-files','lecture-files',false,52428800) on conflict(id) do update set public=false,file_size_limit=52428800;
drop policy if exists teaching_files_select on storage.objects;drop policy if exists teaching_files_insert on storage.objects;drop policy if exists teaching_files_update on storage.objects;drop policy if exists teaching_files_delete on storage.objects;
create policy teaching_files_select on storage.objects for select to authenticated using(bucket_id='lecture-files' and (storage.foldername(name))[1]=auth.uid()::text);create policy teaching_files_insert on storage.objects for insert to authenticated with check(bucket_id='lecture-files' and (storage.foldername(name))[1]=auth.uid()::text);create policy teaching_files_update on storage.objects for update to authenticated using(bucket_id='lecture-files' and (storage.foldername(name))[1]=auth.uid()::text) with check(bucket_id='lecture-files' and (storage.foldername(name))[1]=auth.uid()::text);create policy teaching_files_delete on storage.objects for delete to authenticated using(bucket_id='lecture-files' and (storage.foldername(name))[1]=auth.uid()::text);
